import { createDrawer, type Drawer as DrawerController, type DrawerSide } from "@cssints/headless";
import { Portal } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, createUniqueId, merge, omit, Show, untrack, useContext } from "solid-js";

import { Button } from "./button.tsx";
import { createOverlayMotion, type OverlayMotion } from "./overlay-motion.ts";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface DrawerProps {
  /** Controlled: the host owns the open state and this is the only thing that changes it. */
  readonly open?: boolean;
  /** Open at mount; ignored while `open` is set. */
  readonly defaultOpen?: boolean;
  /** A request to change the open state: uncontrolled it is accepted, controlled the host may ignore it. */
  readonly onOpenChange?: (open: boolean) => void;
  /** The edge the panel is anchored to: a side rail, or the bottom sheet. @default "right" */
  readonly side?: DrawerSide;
  /** `aria-modal`, the Tab trap, the scroll lock and the backdrop (default `true`). */
  readonly modal?: boolean;
  /** A backdrop click or an outside press closes it (default `true`). */
  readonly dismissable?: boolean;
  /**
   * The panel enters and leaves on `@cssints/machine` (`closed`, `entering`, `open`, `leaving`) and the layer is
   * unmounted only at `closed`. The primitive still owns the open state and the whole APG contract; read once.
   */
  readonly animated?: boolean;
  /** The motion preference; left out, `prefers-reduced-motion: reduce` is read once. */
  readonly reducedMotion?: boolean;
  /** Every animation the layer starts, once, after `animate()`: a test pauses it and steps the timeline. */
  readonly onAnimate?: (animation: Animation) => void;
  readonly id?: string;
  /** The element the layer is portalled into (default `document.body`), for a host with its own overlay root. */
  readonly mount?: Element;
  readonly children?: JSX.Element;
}

export interface DrawerTriggerProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerHeaderProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerTitleProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerBodyProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerFooterProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerCloseProps {
  /** The accessible name of the icon button (default `"Close"`). */
  readonly label?: string;
  readonly class?: string;
  readonly children?: JSX.Element;
}

const DrawerContext = createContext<{
  readonly drawer: DrawerController;
  /** The title's id: the primitive puts it on `aria-labelledby`, so the panel is named by its heading. */
  readonly titleId: string;
  readonly mount: () => Element | undefined;
  readonly animated: boolean;
  readonly motion: OverlayMotion;
}>();

// One positioned layer for the backdrop and the panel, out of the page's flow and over everything but a toast. It never takes
// the page's pointer itself: the panel turns that back on, and so does the backdrop when the drawer is modal.
const layerClass = css.cn(
  css.position("fixed"),
  css.inset("0"),
  // `z-index` takes an `<integer>`, which a `number` token is not: the class reads the token by hand, as the dialog's layer
  css.zIndex("var(--z-dialog)"),
  css.pointerEvents("none"),
);

const backdropClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.bg(t.color.scrim),
  css.pointerEvents("auto"),
);

// The panel is edge-anchored: a rail on the left or the right, or a sheet across the bottom. It stays in the DOM while closed
// and hides with `visibility` rather than the `hidden` attribute, so the slide can play both ways and the primitive can move
// the focus into it before the first open frame (a `display: none` panel cannot take the focus).
const panel = css.cv({
  base: css.cn(
    css.position("absolute"),
    css.display("flex"),
    css.flexDirection("column"),
    css.margin("0"),
    css.overflow("hidden"),
    css.pointerEvents("auto"),
    css.color(t.color.text),
    css.boxShadow(t.shadow.popover),
    // the panel takes the focus itself (`tabindex="-1"`) when it holds nothing focusable: a ring around the whole panel is noise
    css.outline("none"),
  ),
  variants: {
    side: {
      left: css.cn(
        css.top("0"),
        css.bottom("0"),
        css.left("0"),
        css.width("min(22rem, 100vw)"),
        css.maxWidth("100%"),
        css.bg(t.color.overlayBackground),
        css.borderInlineEnd("1px solid", t.color.overlayBorder),
      ),
      right: css.cn(
        css.top("0"),
        css.bottom("0"),
        css.right("0"),
        css.width("min(22rem, 100vw)"),
        css.maxWidth("100%"),
        css.bg(t.color.overlayBackground),
        css.borderInlineStart("1px solid", t.color.overlayBorder),
      ),
      // the sheet: full width, its top corners rounded and its own surface token, and a height the body scrolls inside
      bottom: css.cn(
        css.left("0"),
        css.right("0"),
        css.bottom("0"),
        css.width("100%"),
        css.maxHeight("85dvh"),
        css.bg(t.color.sheetBackground),
        css.borderTop("1px solid", t.color.overlayBorder),
        css.borderStartStartRadius(t.radius.xl),
        css.borderStartEndRadius(t.radius.xl),
      ),
    },
  },
  defaultVariants: { side: "right" },
});

// The slide reads one state off `data-state` (`right-open`, `bottom-closed`, ...), so exactly one rule matches and no two
// declarations of the same property compete: closed it is off screen and invisible, open it is in place. With reduced motion
// there is no transition, so `visibility` flips at once instead of waiting for a slide that does not happen.
const panelMotion = css.cn(
  css.visibility("hidden"),
  css.attr("data-state", "left-closed")(css.transform("translateX(-100%)")),
  css.attr("data-state", "right-closed")(css.transform("translateX(100%)")),
  css.attr("data-state", "bottom-closed")(css.transform("translateY(100%)")),
  css.attr("data-state", "left-open")(css.visibility("visible"), css.transform("none")),
  css.attr("data-state", "right-open")(css.visibility("visible"), css.transform("none")),
  css.attr("data-state", "bottom-open")(css.visibility("visible"), css.transform("none")),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.cn(
      css.transition("transform 200ms ease-out, visibility 0s"),
      css.attr(
        "data-state",
        "left-closed",
      )(css.transition("transform 200ms ease-out, visibility 0s linear 200ms")),
      css.attr(
        "data-state",
        "right-closed",
      )(css.transition("transform 200ms ease-out, visibility 0s linear 200ms")),
      css.attr(
        "data-state",
        "bottom-closed",
      )(css.transition("transform 200ms ease-out, visibility 0s linear 200ms")),
    ),
  ),
);

// The animated panel: the box's own ends and no CSS transition (the machine's animation covers the way between them).
// `closed` is the edge the panel is anchored to and is out of the page's hit area; `leaving` paints at the same end while
// the animation slides it there, and takes no clicks (a dismissed panel swallows none); `entering` and `open` are in
// place, which is the panel's own base.
const panelPhases = css.cn(
  css.attr(
    "data-state",
    "left-closed",
  )(css.visibility("hidden"), css.transform("translateX(-100%)")),
  css.attr(
    "data-state",
    "right-closed",
  )(css.visibility("hidden"), css.transform("translateX(100%)")),
  css.attr(
    "data-state",
    "bottom-closed",
  )(css.visibility("hidden"), css.transform("translateY(100%)")),
  css.attr(
    "data-state",
    "left-leaving",
  )(css.transform("translateX(-100%)"), css.pointerEvents("none")),
  css.attr(
    "data-state",
    "right-leaving",
  )(css.transform("translateX(100%)"), css.pointerEvents("none")),
  css.attr(
    "data-state",
    "bottom-leaving",
  )(css.transform("translateY(100%)"), css.pointerEvents("none")),
);

// The panel's track: `fraction` 0 is off the panel's own edge, 1 is in place, and a partial one is where a cancelled
// slide stopped.
const drawerFrame = (side: DrawerSide, fraction: number): Keyframe => {
  const out = (1 - fraction) * 100;
  const x = side === "left" ? -out : side === "right" ? out : 0;
  const y = side === "bottom" ? out : 0;
  return { transform: `translate(${x}%, ${y}%)` };
};

const headerClass = css.cn(
  css.display("flex"),
  css.alignItems("start"),
  css.justifyContent("space-between"),
  css.gap(t.space._3),
  css.padding(t.space._4),
  css.borderBottom("1px solid", t.color.overlayBorder),
  css.flex("none"),
);

const titleClass = css.cn(
  css.margin("0"),
  css.fontSize(t.font.sizeLg),
  css.fontWeight("600"),
  css.color(t.color.text),
);

const closeClass = css.cn(
  css.appearance("none"),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.width(t.space._6),
  css.height(t.space._6),
  css.margin("0"),
  css.padding("0"),
  css.border("none"),
  css.borderRadius(t.radius.sm),
  css.bg("transparent"),
  css.color(t.color.muted),
  css.fontSize(t.font.sizeLg),
  css.lineHeight(1),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground), css.color(t.color.text)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const bodyClass = css.cn(
  css.flex("1 1 auto"),
  css.overflowY("auto"),
  css.overscrollBehavior("contain"),
  css.padding(t.space._4),
  css.fontSize(t.font.size),
  css.color(t.color.text),
);

const footerClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("end"),
  css.gap(t.space._2),
  css.padding(t.space._4),
  css.borderTop("1px solid", t.color.overlayBorder),
  css.flex("none"),
);

/**
 * A drawer or bottom sheet, styled: `Drawer.Trigger` opens a panel on the edge of the viewport. `createDrawer` owns the open
 * state (controlled by `open`), the ARIA, the focus into the panel and back to whatever opened it, the Tab cycle, Escape, the
 * backdrop, the outside press and the page's scroll lock; the kit adds the three edges, the slide, the surface and the slots.
 *
 * The panel is named by `DrawerTitle` (`aria-labelledby`) and closes from a `DrawerClose` in its header, the backdrop, Escape
 * or the trigger. `side` and `modal` are the whole presentation switch: `{ side: "bottom" }` is the sheet, a rail is
 * `{ side: "right" }`, and a non-modal rail (`modal={false}`) keeps the page's scroll, focus and clicks.
 */
export const Drawer = (props: DrawerProps): JSX.Element => {
  // the heading names the panel: the id is made here, because `createDrawer` needs it at creation time
  const titleId = createUniqueId();
  const drawer = createDrawer({
    id: props.id,
    get open() {
      return props.open;
    },
    defaultOpen: props.defaultOpen,
    get side() {
      return props.side;
    },
    get modal() {
      return props.modal;
    },
    get dismissable() {
      return props.dismissable;
    },
    labelledby: titleId,
    get onOpenChange() {
      return props.onOpenChange;
    },
  });
  const mount = () => props.mount;
  const animated = untrack(() => props.animated) === true;
  const motion = createOverlayMotion({
    animated,
    open: () => drawer.open(),
    frame: (fraction) => drawerFrame(drawer.side(), fraction),
    get reducedMotion() {
      return props.reducedMotion;
    },
    get onAnimate() {
      return props.onAnimate;
    },
  });
  return (
    <DrawerContext value={{ drawer, titleId, mount, animated, motion }}>
      {props.children}
    </DrawerContext>
  );
};

/** The button that opens the drawer: `Button` unless `render` says otherwise. It is the element with `aria-haspopup`. */
export const DrawerTrigger = (props: DrawerTriggerProps): JSX.Element => {
  const { drawer } = useContext(DrawerContext);
  const rest = omit(props, "render", "class", "children");
  // no `data-part` of its own: the part renders a `Button` by default, and the button owns the attribute, as `Dialog` does
  const merged = merge(rest, drawer.triggerProps, () => ({
    get class() {
      return css.cn(props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children}</Button>
  ));
};

/**
 * The panel and the wash under it, portalled into `document.body` (or `mount`) so an ancestor's `transform`, `filter`,
 * `contain` or `overflow` can neither clip the layer nor become the containing block of its `position: fixed`.
 *
 * With `animated` the layer is mounted only while the box is not `closed` (or while the primitive is open and the box has
 * yet to follow it), so the slide out is played before the panel leaves the page; `data-state` is the box's phase, and
 * the panel keeps no `hidden` attribute (a panel cut from the page mid-slide is the frame `Atomic` rules out). Without
 * it, the panel stays mounted and the CSS transition follows the primitive's open state.
 */
export const DrawerContent = (props: DrawerContentProps): JSX.Element => {
  const { drawer, mount, animated, motion } = useContext(DrawerContext);
  const merged = merge(omit(props, "render", "class", "children"), drawer.contentProps, () => ({
    "data-part": "drawer",
    get "data-side"() {
      return drawer.side();
    },
    get "data-state"() {
      return `${drawer.side()}-${animated ? motion.phase() : drawer.open() ? "open" : "closed"}`;
    },
    // the panel hides with `visibility` (panelMotion, panelPhases), not with `hidden`: the primitive's attribute would cut
    // the slide, make the panel unfocusable at the moment the focus moves into it, and take a leaving panel off the page
    hidden: false,
    get class() {
      return css.cn(panel({ side: drawer.side() }), animated ? panelPhases : panelMotion, props.class);
    },
  }));
  return (
    <Show when={!animated || motion.visible()}>
      <Portal mount={mount()}>
        <div data-part="drawer-layer" class={layerClass}>
          <div {...drawer.backdropProps} data-part="drawer-backdrop" class={backdropClass} />
          {renderPart(props, merged, undefined, (part) => (
            <div
              {...part}
              ref={(element: HTMLDivElement) => {
                motion.attach(element);
              }}
            >
              {props.children}
            </div>
          ))}
        </div>
      </Portal>
    </Show>
  );
};

/** The top of the panel: the title and the close button. */
export const DrawerHeader = (props: DrawerHeaderProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "drawer-header",
      get class() {
        return css.cn(headerClass, props.class);
      },
    },
    undefined,
    (part) => <div {...part}>{props.children}</div>,
  );

/** The panel's visible heading, and the name the primitive points `aria-labelledby` at. */
export const DrawerTitle = (props: DrawerTitleProps): JSX.Element => {
  const { titleId } = useContext(DrawerContext);
  return renderPart(
    props,
    {
      id: titleId,
      "data-part": "drawer-title",
      get class() {
        return css.cn(titleClass, props.class);
      },
    },
    undefined,
    (part) => <h2 {...part}>{props.children}</h2>,
  );
};

/** The panel's body: the only part that scrolls when the content is taller than the edges allow. */
export const DrawerBody = (props: DrawerBodyProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "drawer-body",
      get class() {
        return css.cn(bodyClass, props.class);
      },
    },
    undefined,
    (part) => <div {...part}>{props.children}</div>,
  );

/** The panel's footer: actions, against the bottom edge. */
export const DrawerFooter = (props: DrawerFooterProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "drawer-footer",
      get class() {
        return css.cn(footerClass, props.class);
      },
    },
    undefined,
    (part) => <div {...part}>{props.children}</div>,
  );

/** The close control in the header: a small icon button with an accessible name. */
export const DrawerClose = (props: DrawerCloseProps): JSX.Element => {
  const { drawer } = useContext(DrawerContext);
  return (
    <button
      type="button"
      data-part="drawer-close"
      class={css.cn(closeClass, props.class)}
      aria-label={props.label ?? "Close"}
      onClick={() => {
        // the trigger's handler toggles, which is a close while the drawer is open
        if (drawer.open()) {
          drawer.triggerProps.onClick();
        }
      }}
    >
      {props.children ?? <span aria-hidden="true">×</span>}
    </button>
  );
};

// The machine of an animated modal layer: the box of `specs/patterns/animation.qnt` (closed, entering, open, leaving),
// and nothing of the modal contract. The APG half — focus in and back to the invoker, the Tab cycle, Escape, the
// backdrop, `aria-modal`, the scroll lock — is `specs/apg/dialog-modal.qnt` and stays in `@cssints/headless`
// (`createDialogModal`, `createDrawer`). A `Dialog` or a `Drawer` with `animated` is the two questions together: the
// primitive decides *whether* the layer is open, this machine decides *how* it leaves and enters, and the layer is
// unmounted only at `closed`.
//
// The intents are the primitive's, not the DOM's. The machine follows `open()`: a request a controlled host refuses
// never moves the box (no slide out and back), and the box starts closing only once the open state really changed. That
// is the one place this host differs from the disclosure's, which starts the animation from an intent. Two `close`
// intents in one frame are one dismissal because the machine has no `close` transition while `leaving` — a superseded
// intent, not a debounce — and because `createControllable` asks the host once for an intent it is still waiting on.
//
// Leaving a state cancels the effect the machine issued, and a cancelled animation's own late completion carries the
// dead handle's id, which the machine drops before it looks at a transition (`CancelledFinishIgnored`,
// `StaleCarriesCancelled`). A reversal keeps the box where it is: the host reads the running animation's `currentTime`
// before it cancels it, so the replacement starts at that fraction (`ReversalKeepsPosition`). With
// `prefers-reduced-motion: reduce` an intent lands in one step and no transition is entered (`ReducedMotionSkips`).
import {
  type ConfigEvent,
  createMachine,
  defineMachine,
  type EffectHandle,
  type Machine,
  type Transition,
  type TransitionList,
} from "@cssints/machine";
import { type MachineStore, createMachineStore } from "@cssints/machine/solid";
import { type Accessor, createEffect, onCleanup, untrack } from "solid-js";

/** How long a full open or close takes: the drawer's slide and the dialog's fade are one track. */
export const OVERLAY_MOTION_DURATION = 200;

/** The box: the four states `specs/patterns/animation.qnt` calls `visual`. */
export type OverlayMotionPhase = "closed" | "entering" | "open" | "leaving";

/** The machine's context: the accepted intent, what the box has settled at, and the motion preference. */
export interface OverlayMotionContext {
  /** The primitive's open state (`dialog.open()`): what `aria-expanded` and `aria-modal` say. */
  readonly logical: boolean;
  /** What the box has settled at; only an effect's completion moves it. */
  readonly committed: "closed" | "open";
  /** `prefers-reduced-motion: reduce` (or the `reducedMotion` override): no transition is entered. */
  readonly reduced: boolean;
}

// a type alias, not an interface: `PayloadMap` is an index signature, and only an alias is assignable to one
type OverlayMotionPayloads = {
  readonly open: undefined;
  readonly close: undefined;
  readonly finish: { readonly id: number };
  readonly motion: { readonly reduced: boolean };
};

/** The machine's events: the protocol's own, not the DOM's. */
export type OverlayMotionEvent =
  | { readonly type: "open" }
  | { readonly type: "close" }
  | { readonly type: "finish"; readonly id: number }
  | { readonly type: "motion"; readonly reduced: boolean };

/** The running machine, as the components and their tests name it. */
export type OverlayMotionMachine = Machine<
  OverlayMotionContext,
  OverlayMotionPhase,
  OverlayMotionEvent
>;

type OverlayMotionConfig = ConfigEvent<OverlayMotionPayloads>;

// A same-direction intent has no transition at all: the machine drops it, so the running effect is neither cancelled
// nor restarted. Reduced motion is the same list's first entry: the box lands at the intent in one step, no effect.
const toward = (open: boolean): TransitionList<OverlayMotionContext, OverlayMotionConfig> => [
  {
    guard: (context) => context.reduced,
    target: open ? "open" : "closed",
    assign: { logical: open, committed: open ? "open" : "closed" },
  },
  {
    target: open ? "entering" : "leaving",
    assign: { logical: open },
    effect: { type: "animate", to: open ? "open" : "closed" },
  },
];

// The preference moves while the box is still: keep the phase, nothing else changes.
const followMotion = (
  phase: OverlayMotionPhase,
): Transition<OverlayMotionContext, OverlayMotionConfig> => ({
  target: phase,
  assign: (context, event) => ({
    reduced: event.type === "motion" ? event.reduced : context.reduced,
  }),
});

// The preference turns on mid-flight: the effect is cancelled by leaving the state, the box lands at the intent.
const stopMotion = (
  target: "open" | "closed",
): Transition<OverlayMotionContext, OverlayMotionConfig> => ({
  target,
  guard: (_context, event) => event.type === "motion" && event.reduced,
  assign: { reduced: true, committed: target },
});

const settle = (target: "open" | "closed"): Transition<OverlayMotionContext, OverlayMotionConfig> => ({
  target,
  assign: { committed: target },
});

/**
 * The protocol as data, for the components and for a harness: four states, four events, and no `close` in `leaving`
 * (a second dismissal is a superseded intent) and no `open` in `open` (a repeated open is none). `start` follows the
 * primitive, so a dialog that is open at mount is painted open rather than entered.
 */
export const overlayMotionDefinition = (
  reduced: boolean,
  start: "open" | "closed" = "closed",
) =>
  defineMachine<OverlayMotionPayloads>()({
    start,
    initial: { logical: start === "open", committed: start, reduced },
    states: {
      closed: {
        on: { open: toward(true), motion: followMotion("closed") },
      },
      entering: {
        on: { close: toward(false), finish: settle("open"), motion: stopMotion("open") },
      },
      open: {
        on: { close: toward(false), motion: followMotion("open") },
      },
      leaving: {
        on: { open: toward(true), finish: settle("closed"), motion: stopMotion("closed") },
      },
    },
  });

/** A frame of the panel on the box's track: 0 is closed, 1 is open. */
export type OverlayFrame = (fraction: number) => Keyframe;

/** What the host needs: the primitive's open state, the panel's frames, and the preference. */
export interface OverlayMotionOptions {
  /** The primitive's open state: the machine follows it, so a request the host refuses never moves the box. */
  readonly open: Accessor<boolean>;
  /** Structural, read once: off, the box lands in one microtask and no animation starts. */
  readonly animated: boolean;
  /** The panel's frames: the dialog fades and lifts, the drawer slides off its own edge. */
  readonly frame: OverlayFrame;
  /** The motion preference; left out, `prefers-reduced-motion: reduce` is read once. */
  readonly reducedMotion?: boolean | undefined;
  /** Every animation the host starts, once, after `animate()`: a test pauses it and steps the timeline. */
  readonly onAnimate?: ((animation: Animation) => void) | undefined;
}

/** The machine as the layer reads it: a phase, a presence, and the panel the effects run on. */
export interface OverlayMotion {
  readonly machine: OverlayMotionMachine;
  readonly store: MachineStore<
    OverlayMotionContext,
    OverlayMotionPhase,
    OverlayMotionEvent
  >;
  /** The box, from the committed store: one field, and a reader of it does not re-run for the others. */
  readonly phase: Accessor<OverlayMotionPhase>;
  /** The layer is mounted: the box is not closed, or the primitive is open and the box has yet to follow it. */
  readonly visible: Accessor<boolean>;
  readonly attach: (element: HTMLElement | undefined) => void;
}

interface LiveAnimation {
  readonly handle: EffectHandle;
  readonly animation: Animation;
  readonly from: number;
  readonly to: number;
  readonly duration: number;
}

const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * Run the box for one layer. Call it in a component body: the store and its projections belong to the component, and
 * disposing it unsubscribes from the machine and settles it.
 */
export const createOverlayMotion = (options: OverlayMotionOptions): OverlayMotion => {
  const animated = options.animated;
  const machine: OverlayMotionMachine = createMachine(
    overlayMotionDefinition(
      untrack(() => options.reducedMotion) ?? prefersReducedMotion(),
      untrack(() => options.open()) ? "open" : "closed",
    ),
  );
  const store = createMachineStore(machine);
  const view = store.projection(
    (draft, state) => {
      draft.visible = state.phase !== "closed";
    },
    { visible: false },
  );

  let panel: HTMLElement | undefined;
  /** The live animation, or `undefined` at rest (and for the instant between a cancel and its replacement). */
  let live: LiveAnimation | undefined;
  /** Where a cancelled animation stopped: the reversal's start. */
  let carried: number | undefined;

  const fractionOf = (running: LiveAnimation): number => {
    const time = Number(running.animation.currentTime ?? 0);
    return running.duration === 0 ? 0 : Math.min(1, Math.max(0, time / running.duration));
  };

  const offEffect = machine.onEffect((handle) => {
    const to = handle.spec.to === "open" ? 1 : 0;
    // a reversal keeps the box where it was; a start begins at the end the box is already at
    const from = carried ?? (to === 1 ? 0 : 1);
    carried = undefined;
    const element = panel;
    if (element === undefined || !animated) {
      // no motion asked for, or nothing mounted to animate: the box lands at once, and the finish is a microtask so a
      // transition is still one delivery
      queueMicrotask(() => machine.send({ type: "finish", id: handle.id }));
      return;
    }
    const distance = Math.abs(to - from);
    // the box moves at a constant rate, so the duration is what is left to travel; `fill: none` because the panel's own
    // state styling is the animation's end in either direction
    const duration = OVERLAY_MOTION_DURATION * Math.max(distance, 0.001);
    const animation = element.animate([options.frame(from), options.frame(to)], {
      duration,
      easing: "linear",
      fill: "none",
    });
    // the ends, for a test that steps the timeline; the id is the least visible place to keep them
    animation.id = `${from}:${to}`;
    live = { handle, animation, from, to, duration };
    options.onAnimate?.(animation);
    const done = (): void => {
      if (live?.handle.id === handle.id) {
        live = undefined;
      }
      animation.cancel();
      // a completion, and a cancelled animation's own late one: the machine drops the latter by its id
      machine.send({ type: "finish", id: handle.id });
    };
    animation.finished.then(done, done);
  });

  const offCancel = machine.onCancel((handle) => {
    if (live?.handle.id !== handle.id) {
      return;
    }
    const cancelled = live;
    // read before `cancel()`: a cancelled animation's `currentTime` is null
    carried = fractionOf(cancelled);
    live = undefined;
    cancelled.animation.cancel();
  });

  // The machine follows the primitive. The delivery is a microtask because an effect runs in an owned scope, where the
  // store refuses a write; the layer's presence does not wait for it — it reads `open()` too, so the panel is in the
  // DOM before the primitive moves the focus into it.
  createEffect(
    () => options.open(),
    (open) => {
      queueMicrotask(() => {
        if (open !== machine.getState().context.logical) {
          machine.send({ type: open ? "open" : "close" });
        }
      });
    },
  );

  createEffect(
    () => options.reducedMotion,
    (reduced) => {
      if (reduced === undefined) {
        return;
      }
      queueMicrotask(() => {
        if (reduced !== machine.getState().context.reduced) {
          machine.send({ type: "motion", reduced });
        }
      });
    },
  );

  onCleanup(() => {
    offEffect();
    offCancel();
    machine.destroy();
  });

  // The box as the layer shows it (`data-state`). The machine follows `open()` on the next microtask, so for the flush
  // that mounts the panel — before the primitive can move the focus into it — the box is where it is heading: `entering`,
  // or `open` at once when the preference skips the transition. A mounted layer is never shown at the `closed` end.
  const shown = (): OverlayMotionPhase => {
    const phase = store.state.phase;
    if (phase !== "closed" || !options.open()) {
      return phase;
    }
    return machine.getState().context.reduced ? "open" : "entering";
  };

  return {
    machine,
    store,
    phase: shown,
    visible: () => options.open() || view.visible,
    attach: (element) => {
      panel = element;
    },
  };
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import { createSignal } from "solid-js";

import type { DrawerSide } from "@cssints/headless";
import { Button } from "./button.tsx";
import { Input } from "./input.tsx";
import {
  Drawer,
  DrawerBody,
  DrawerClose,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "./drawer.tsx";

/** What a mounted demo hands the test: where it lives, what the controlled host saw, and a teardown. */
export interface MountedDrawer {
  readonly root: HTMLElement;
  /** Every open state the controlled drawer's host was asked for, in order. */
  readonly requests: ReadonlyArray<boolean>;
  /** The controlled host stops accepting requests: the next close is refused. */
  readonly hold: () => void;
  readonly dispose: () => void;
}

/**
 * Mounts the styled drawer in ordinary use: a controlled right-hand rail with a small form (and a `Cancel` in its footer),
 * and an uncontrolled bottom sheet. The trigger opens each; the primitive owns the rest. The host can `hold()` to show a
 * controlled drawer refusing to close.
 */
export const mountDrawer = (): MountedDrawer => {
  const root = document.createElement("div");
  document.body.append(root);
  const requests: boolean[] = [];
  let accept = true;
  const [filters, setFilters] = createSignal(false);

  const dispose = render(
    () => (
      <div>
        <Drawer
          open={filters()}
          onOpenChange={(open) => {
            requests.push(open);
            if (accept) {
              setFilters(open);
            }
          }}
        >
          <DrawerTrigger>Filters</DrawerTrigger>
          <DrawerContent>
            <DrawerHeader>
              <DrawerTitle>Filters</DrawerTitle>
              <DrawerClose />
            </DrawerHeader>
            <DrawerBody>
              <Input aria-label="Search" placeholder="Search the report" />
            </DrawerBody>
            <DrawerFooter>
              <Button tone="quiet" onClick={() => setFilters(false)}>
                Cancel
              </Button>
              <Button tone="accent" onClick={() => setFilters(false)}>
                Apply
              </Button>
            </DrawerFooter>
          </DrawerContent>
        </Drawer>
        <Drawer side="bottom">
          <DrawerTrigger>Open the sheet</DrawerTrigger>
          <DrawerContent>
            <DrawerHeader>
              <DrawerTitle>Share</DrawerTitle>
              <DrawerClose />
            </DrawerHeader>
            <DrawerBody>A bottom sheet for the action that belongs to the whole page.</DrawerBody>
            <DrawerFooter>
              <Button tone="accent">Copy link</Button>
            </DrawerFooter>
          </DrawerContent>
        </Drawer>
      </div>
    ),
    root,
  );

  return {
    root,
    requests,
    hold: () => {
      accept = false;
    },
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

/** What an animated drawer hands its test: the layer, the host's requests, and the box's own timeline. */
export interface MountedMotionDrawer {
  readonly root: HTMLElement;
  /** Every open state the host was asked for, in order. */
  readonly requests: ReadonlyArray<boolean>;
  /** The controlled host stops accepting requests: the next close is refused. */
  readonly hold: () => void;
  readonly trigger: () => HTMLButtonElement;
  /** The panel, or `null` while the layer is unmounted. */
  readonly panel: () => HTMLElement | null;
  readonly layer: () => HTMLElement | null;
  /** The panel's `data-state` (`<side>-<phase>`), or `null` while the layer is unmounted. */
  readonly phase: () => string | null;
  /** Every phase the panel announced, in order (a MutationObserver, so a phase that lasted a frame is in it). */
  readonly phases: () => ReadonlyArray<string>;
  /** How many times the trigger took the focus back. */
  readonly focuses: () => number;
  /** Every animation the layer started, in order; the fixture pauses each one. */
  readonly animations: () => ReadonlyArray<Animation>;
  /** Move the running animation to `fraction` of its track (0 off the edge .. 1 in place). */
  readonly seek: (fraction: number) => void;
  /** Finish the running animation now, as the browser would at its end. */
  readonly finish: () => void;
  readonly dispose: () => void;
}

export interface MountAnimatedDrawerOptions {
  /** The host owns the open state, in a signal the test can write and refuse. */
  readonly controlled?: boolean | undefined;
  /** The motion preference, as the host would pass it. */
  readonly reducedMotion?: boolean | undefined;
  readonly side?: DrawerSide | undefined;
  /** A backdrop click or an outside press does not close it. */
  readonly dismissable?: boolean | undefined;
}

let motionCounter = 0;

/**
 * Mounts one animated drawer: the panel is on the machine, the fixture pauses every animation it starts (so a test owns
 * the timeline), and the host records every request when `controlled`.
 */
export const mountAnimatedDrawer = (
  options: MountAnimatedDrawerOptions = {},
): MountedMotionDrawer => {
  const root = document.createElement("div");
  document.body.append(root);
  const id = `fixture-motion-drawer-${(motionCounter += 1)}`;
  const requests: boolean[] = [];
  const animations: Animation[] = [];
  const phases: string[] = [];
  let accept = true;
  let focusCount = 0;
  const [open, setOpen] = createSignal(false);

  const panel = (): HTMLElement | null => document.getElementById(`${id}-content`);
  const layer = (): HTMLElement | null => panel()?.closest('[data-part="drawer-layer"]') ?? null;
  const trigger = (): HTMLButtonElement => {
    const element = document.getElementById(`${id}-trigger`);
    if (!(element instanceof HTMLButtonElement)) {
      throw new Error("the drawer did not render its trigger");
    }
    return element;
  };

  const observer = new MutationObserver(() => {
    const phase = panel()?.getAttribute("data-state") ?? null;
    if (phase !== null && phases.at(-1) !== phase) {
      phases.push(phase);
    }
  });
  observer.observe(document.body, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ["data-state"],
  });

  const dispose = render(
    () => (
      <Drawer
        id={id}
        side={options.side}
        animated
        reducedMotion={options.reducedMotion}
        dismissable={options.dismissable}
        open={options.controlled === true ? open() : undefined}
        onOpenChange={(next) => {
          requests.push(next);
          if (options.controlled === true && accept) {
            setOpen(next);
          }
        }}
        onAnimate={(animation) => {
          animations.push(animation);
          animation.pause();
        }}
      >
        <DrawerTrigger>Filters</DrawerTrigger>
        <DrawerContent>
          <DrawerHeader>
            <DrawerTitle>Filters</DrawerTitle>
            <DrawerClose />
          </DrawerHeader>
          <DrawerBody>
            <Input aria-label="Search" placeholder="Search the report" />
          </DrawerBody>
          <DrawerFooter>
            <Button tone="quiet" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button tone="accent" onClick={() => setOpen(false)}>
              Apply
            </Button>
          </DrawerFooter>
        </DrawerContent>
      </Drawer>
    ),
    root,
  );

  // count the focus the primitive gives back, instead of watching the activeElement after the fact
  const focus = trigger().focus.bind(trigger());
  trigger().focus = () => {
    focusCount += 1;
    focus();
  };

  return {
    root,
    requests,
    hold: () => {
      accept = false;
    },
    trigger,
    panel,
    layer,
    phase: () => panel()?.getAttribute("data-state") ?? null,
    phases: () => [...phases],
    focuses: () => focusCount,
    animations: () => [...animations],
    seek: (fraction) => {
      for (const animation of panel()?.getAnimations() ?? []) {
        const duration = Number(animation.effect?.getTiming().duration ?? 0);
        animation.currentTime = duration * fraction;
      }
    },
    finish: () => {
      for (const animation of panel()?.getAnimations() ?? []) {
        animation.finish();
      }
    },
    dispose: () => {
      observer.disconnect();
      dispose();
      root.remove();
    },
  };
};

import { harness } from "@cssints/machine";
import { afterEach, describe, expect, it } from "vite-plus/test";

import { overlayMotionDefinition } from "./overlay-motion.ts";
import {
  type MountAnimatedDrawerOptions,
  type MountedDrawer,
  type MountedMotionDrawer,
  mountAnimatedDrawer,
  mountDrawer,
} from "./drawer.fixture";

/** Solid 2 delivers events through its delegated listener on a later turn. */
const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

/** The slide is 200 ms: the geometry is final only after it, as a reader sees it. */
const settleSlide = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 260));

const live: MountedDrawer[] = [];

const mounted = (): MountedDrawer => {
  const instance = mountDrawer();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends HTMLElement>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`drawer: no ${selector}`);
  }
  return element;
};

/** The trigger of a drawer, by its label: the fixture has one per drawer. */
const trigger = (root: HTMLElement, label: string): HTMLButtonElement => {
  const found = [...root.querySelectorAll<HTMLButtonElement>('[aria-haspopup="dialog"]')].find(
    (element) => element.textContent?.trim() === label,
  );
  if (found === undefined) {
    throw new Error(`drawer: no trigger "${label}"`);
  }
  return found;
};

/** A panel by the text of its title: both drawers are in the DOM, closed ones included. */
const panel = (title: string): HTMLElement => {
  const found = [...document.querySelectorAll<HTMLElement>('[data-part="drawer"]')].find(
    (element) => element.querySelector('[data-part="drawer-title"]')?.textContent === title,
  );
  if (found === undefined) {
    throw new Error(`drawer: no panel "${title}"`);
  }
  return found;
};

const inside = (root: HTMLElement, name: string): HTMLElement =>
  required(root, `[data-part="${name}"]`);

const click = async (element: HTMLElement): Promise<void> => {
  element.click();
  await settle();
};

/** A key on whatever holds the focus, as a reader's would arrive. */
const press = async (key: string, init: KeyboardEventInit = {}): Promise<void> => {
  const target =
    document.activeElement instanceof HTMLElement ? document.activeElement : document.body;
  target.dispatchEvent(
    new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true, ...init }),
  );
  await settle();
};

const background = (token: string): string => {
  const probe = document.createElement("div");
  probe.style.backgroundColor = `var(${token})`;
  document.body.append(probe);
  const value = getComputedStyle(probe).backgroundColor;
  probe.remove();
  return value;
};

describe("Drawer", () => {
  it("opens from its trigger as a modal dialog", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    const dialog = panel("Filters");

    expect(open.getAttribute("aria-expanded")).toBe("false");
    expect(open.getAttribute("aria-controls")).toBe(dialog.id);
    expect(dialog.getAttribute("role")).toBe("dialog");
    expect(dialog.getAttribute("aria-modal")).toBeNull();
    // a closed rail is off screen and out of the accessibility tree, not in the page's flow
    expect(getComputedStyle(dialog).visibility).toBe("hidden");

    open.focus();
    await click(open);

    expect(open.getAttribute("aria-expanded")).toBe("true");
    expect(dialog.getAttribute("aria-modal")).toBe("true");
    expect(dialog.getAttribute("data-state")).toBe("right-open");
    expect(getComputedStyle(dialog).visibility).toBe("visible");
    // portalled out of the fixture, into the body, so no ancestor can clip it or hold its `position: fixed`
    expect(root.contains(dialog)).toBe(false);
    expect(dialog.closest('[data-part="drawer-layer"]')?.parentElement).toBe(document.body);
  });

  it("names the panel by its title", async () => {
    const { root } = mounted();
    await click(trigger(root, "Filters"));
    const dialog = panel("Filters");
    const title = inside(dialog, "drawer-title");

    expect(dialog.getAttribute("aria-labelledby")).toBe(title.id);
    expect(title.textContent).toBe("Filters");
    // the close control is an icon button with an accessible name
    expect(inside(dialog, "drawer-close").getAttribute("aria-label")).toBe("Close");
  });

  it("moves the focus into the panel, keeps Tab inside, and returns it on Escape", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    open.focus();
    await click(open);
    const dialog = panel("Filters");
    const close = inside(dialog, "drawer-close");
    const footerButtons = [
      ...inside(dialog, "drawer-footer").querySelectorAll<HTMLButtonElement>("button"),
    ];
    const last = footerButtons[footerButtons.length - 1];
    if (last === undefined) {
      throw new Error("drawer: no footer button");
    }

    expect(document.activeElement).toBe(close);

    last.focus();
    await press("Tab");
    expect(document.activeElement).toBe(close);

    close.focus();
    await press("Tab", { shiftKey: true });
    expect(document.activeElement).toBe(last);

    await press("Escape");
    expect(open.getAttribute("aria-expanded")).toBe("false");
    expect(dialog.getAttribute("aria-modal")).toBeNull();
    expect(document.activeElement).toBe(open);
  });

  it("closes on a press on the backdrop", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    open.focus();
    await click(open);
    const backdrop = required<HTMLElement>(document, '[data-part="drawer-backdrop"]');

    expect(backdrop.hidden).toBe(false);
    backdrop.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true, cancelable: true }));
    await settle();

    expect(open.getAttribute("aria-expanded")).toBe("false");
    expect(document.activeElement).toBe(open);
  });

  it("locks the page's scroll while open and releases it on close", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    expect(document.documentElement.style.overflow).toBe("");

    await click(open);
    expect(document.documentElement.style.overflow).toBe("hidden");

    await press("Escape");
    expect(document.documentElement.style.overflow).toBe("");
  });

  it("renders the bottom variant as a full-width sheet on its own surface", async () => {
    const { root } = mounted();
    await click(trigger(root, "Open the sheet"));
    await settleSlide();
    const sheet = panel("Share");
    const style = getComputedStyle(sheet);
    const rect = sheet.getBoundingClientRect();

    // the top corners are the theme's radius, the bottom ones meet the viewport edge
    expect(style.borderTopLeftRadius).not.toBe("0px");
    expect(style.borderTopRightRadius).not.toBe("0px");
    expect(style.borderBottomLeftRadius).toBe("0px");
    expect(Math.round(rect.left)).toBe(0);
    expect(Math.round(rect.width)).toBe(window.innerWidth);
    expect(Math.round(rect.bottom)).toBe(window.innerHeight);
    expect(style.maxHeight).not.toBe("none");
    // the sheet's surface is a token of its own, not the rail's
    expect(style.backgroundColor).toBe(background("--color-sheet-background"));
  });

  it("lets a controlled host refuse to close", async () => {
    const instance = mounted();
    const open = trigger(instance.root, "Filters");
    await click(open);
    expect(open.getAttribute("aria-expanded")).toBe("true");

    instance.hold();
    await press("Escape");

    expect(instance.requests.at(-1)).toBe(false);
    expect(open.getAttribute("aria-expanded")).toBe("true");
    expect(panel("Filters").getAttribute("aria-modal")).toBe("true");
  });
});

// The animated drawer is the same primitive and the same box as the dialog (`apps/ui/.../overlay-motion.ts`), so its
// harness cases are the protocol's own here as well: what differs between the two components is the skin.
const animated: MountedMotionDrawer[] = [];

const animatedDrawer = (options: MountAnimatedDrawerOptions = {}): MountedMotionDrawer => {
  const instance = mountAnimatedDrawer(options);
  animated.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of animated.splice(0)) {
    instance.dispose();
  }
});

const openTheDrawer = async (instance: MountedMotionDrawer): Promise<void> => {
  instance.trigger().focus();
  instance.trigger().click();
  await settle();
  instance.finish();
  await settle();
};

describe("Drawer x the animated box (harness)", () => {
  it("a close during the close is a superseded intent, not a second effect", () => {
    const h = harness(overlayMotionDefinition(false));
    h.send({ type: "open" });
    h.send({ type: "finish", id: h.machine.effects()[0]?.id ?? 0 });
    h.send({ type: "close" });
    const leaving = h.machine.effects()[0]?.id;
    h.send({ type: "close" });
    h.send({ type: "close" });
    expect(h.machine.getState().state).toBe("leaving");
    expect(h.machine.effects().map((handle) => handle.id)).toEqual([leaving]);
  });

  it("reduced motion has no leaving phase to animate", () => {
    const h = harness(overlayMotionDefinition(true));
    h.send({ type: "open" });
    h.send({ type: "close" });
    expect(h.log.map((entry) => entry.to)).toEqual(["open", "closed"]);
    expect(h.machine.effects()).toEqual([]);
  });
});

describe("Drawer x the animated box (real DOM)", () => {
  it("slides the panel out through leaving and unmounts it only at closed", async () => {
    const instance = animatedDrawer();
    expect(instance.layer()).toBeNull();

    instance.trigger().focus();
    instance.trigger().click();
    await settle();
    expect(instance.phase()).toBe("right-entering");
    const panel = instance.panel();
    expect(panel).not.toBeNull();

    instance.finish();
    await settle();
    expect(instance.phase()).toBe("right-open");
    expect(getComputedStyle(panel as HTMLElement).visibility).toBe("visible");

    await press("Escape");
    expect(instance.phase()).toBe("right-leaving");
    expect(instance.panel()).toBe(panel);
    expect(instance.layer()).not.toBeNull();
    expect(getComputedStyle(panel as HTMLElement).visibility).not.toBe("hidden");

    instance.finish();
    await settle();
    expect(instance.panel()).toBeNull();
    expect(instance.layer()).toBeNull();
    expect(instance.phases()).toEqual(["right-entering", "right-open", "right-leaving"]);
  });

  it("slides a bottom sheet along its own edge", async () => {
    const instance = animatedDrawer({ side: "bottom" });
    instance.trigger().focus();
    instance.trigger().click();
    await settle();
    const animation = instance.animations().at(-1);
    const frames = (animation?.effect as KeyframeEffect | null)?.getKeyframes() ?? [];
    expect(frames[0]?.transform).toBe("translate(0%, 100%)");
    expect(frames.at(-1)?.transform).toBe("translate(0%, 0%)");
    expect(instance.phase()).toBe("bottom-entering");
  });

  it("gives the focus back once and starts no second close on an Escape during the close", async () => {
    const instance = animatedDrawer({ controlled: true });
    await openTheDrawer(instance);
    expect(instance.requests).toEqual([true]);
    const base = instance.focuses();

    await press("Escape");
    expect(instance.phase()).toBe("right-leaving");
    expect(instance.focuses()).toBe(base + 1);
    const started = instance.animations().length;

    await press("Escape");
    expect(instance.phase()).toBe("right-leaving");
    expect(instance.focuses()).toBe(base + 1);
    expect(instance.animations()).toHaveLength(started);
    // one dismissal, one request
    expect(instance.requests).toEqual([true, false]);
  });

  it("reverses a closing drawer from where it stopped", async () => {
    const instance = animatedDrawer();
    await openTheDrawer(instance);
    const panel = instance.panel();

    await press("Escape");
    instance.seek(0.25);
    instance.trigger().click();
    await settle();

    expect(instance.phase()).toBe("right-entering");
    expect(instance.animations().at(-1)?.id.split(":")[0]).toBe("0.25");
    expect(instance.panel()).toBe(panel);

    await settle();
    expect(instance.phase()).toBe("right-entering");
  });

  it("closes in one step with reduced motion", async () => {
    const instance = animatedDrawer({ reducedMotion: true });
    instance.trigger().focus();
    instance.trigger().click();
    await settle();
    expect(instance.phase()).toBe("right-open");
    expect(instance.animations()).toEqual([]);

    await press("Escape");
    expect(instance.panel()).toBeNull();
    expect(instance.phases()).toEqual(["right-open"]);
  });

  it("asks the host once for a backdrop click and an Escape in the same frame", async () => {
    const instance = animatedDrawer({ controlled: true });
    await openTheDrawer(instance);
    const base = instance.focuses();
    const wash = document.querySelector<HTMLElement>('[data-part="drawer-backdrop"]');
    if (wash === null) {
      throw new Error("drawer: no backdrop");
    }
    wash.click();
    await press("Escape");
    expect(instance.requests).toEqual([true, false]);
    expect(instance.focuses()).toBe(base + 1);
  });

  it("keeps a leaving panel painted and out of the pointer", async () => {
    const instance = animatedDrawer();
    await openTheDrawer(instance);
    const layer = instance.layer();
    const panel = instance.panel();
    if (layer === null || panel === null) {
      return;
    }
    expect(getComputedStyle(panel).pointerEvents).toBe("auto");

    await press("Escape");
    expect(panel.hasAttribute("hidden")).toBe(false);
    expect(getComputedStyle(panel).display).not.toBe("none");
    expect(getComputedStyle(panel).pointerEvents).toBe("none");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
